        buffer_append(code, (const char *)add_rbx, 4);
        uint8_t dec_r12[3] = {0x49, 0xff, 0xcc};
        buffer_append(code, (const char *)dec_r12, 3);
        uint8_t jnz[2] = {0x75, 0xf5};
        buffer_append(code, (const char *)jnz, 2);
