            int cmp = (ord[j - 1].prio > key.prio) - (ord[j - 1].prio < key.prio);
            if (cmp == 0)
                cmp = (ord[j - 1].idx > key.idx) - (ord[j - 1].idx < key.idx);
            if (cmp <= 0) break;
