        if (mods[i]->bss_align > max_bss_align) max_bss_align = mods[i]->bss_align;
        if (mods[i]->tdata_align > max_td_align) max_td_align = mods[i]->tdata_align;
        if (mods[i]->tbss_align > max_tbss_align) max_tbss_align = mods[i]->tbss_align;
